
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_lg93_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_lg93", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.272499728108039e+00, -4.191328252801546e+00, -4.077878296833209e+00, -3.921375930105976e+00, -3.709627717032952e+00, -3.431299051907498e+00, -3.080569764633546e+00, -2.661358931420276e+00, -2.182157204868528e+00, -1.653877578398815e+00, -1.110501749170267e+00, -7.091851388970190e-01, -5.985037728466690e-01, -5.007956559787667e-01, -3.779852561984750e-01, -2.478032398237545e-01, -1.367473852023930e-01, -6.118717974570364e-02, -2.052663301963450e-02, -4.409417532963411e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


